#!/usr/bin/env bash
# Check that the expected.txt of every example is what its oracle produces today.
#
# Usage: scripts/check-expected.sh
#
# An example directory under distilled/*/examples/ and original/*/examples/ is defined by one of:
#   program.lua  expected.txt is the output of real Lua 5.4 (needs lua5.4 on the PATH)
#   goal.txt     expected.txt is generated by scripts/gen-kernel.sh
# Each entry's FIDELITY.md (or README.md for an original entry) repeats the command that
# regenerates its files. Never edit an expected.txt by hand.
set -euo pipefail

root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$root"
status=0
shopt -s nullglob

for dir in distilled/*/examples/*/ original/*/examples/*/; do
    dir=${dir%/}
    if [[ -f $dir/program.lua ]]; then
        if ! lua5.4 "$dir/program.lua" | diff -u "$dir/expected.txt" - >&2; then
            echo "FAIL $dir: expected.txt is not the output of lua5.4 program.lua" >&2
            status=1
        fi
    elif [[ -f $dir/goal.txt ]]; then
        scripts/gen-kernel.sh --check "$dir" || status=1
    else
        echo "FAIL $dir: has neither program.lua nor goal.txt" >&2
        status=1
    fi
done

if [[ $status -eq 0 ]]; then
    echo "ok: every expected.txt is reproduced by its oracle"
fi
exit "$status"
